-- RAMA Door seed data. Generated by scripts/generate-seed.mjs. Run after the migration.

on conflict (id) do update set name = excluded.name, nickname = excluded.nickname, rates = excluded.rates;
select setval('public.creators_id_seq', (select max(id) from public.creators));

-- SAMPLE outdoor sites
on conflict (id) do nothing;
select setval('public.outdoor_sites_id_seq', (select max(id) from public.outdoor_sites));

-- SAMPLE booked weeks, relative to next Monday
on conflict do nothing;

-- Media outlets (real names, SAMPLE rates)
on conflict (id) do nothing;

-- SAMPLE PR packages
on conflict (key) do nothing;
